from collections import deque


def avoid_count(n: int, alphabet: str, banned: list[str]) -> int:
    MOD = 1_000_000_007
    if n == 0:
        return 1
    k = len(alphabet)
    if not banned:
        return pow(k, n, MOD)

    char_to_idx = {c: i for i, c in enumerate(alphabet)}
    trans = [[-1] * k]
    bad = [False]

    for word in banned:
        node = 0
        for ch in word:
            ci = char_to_idx[ch]
            nxt = trans[node][ci]
            if nxt == -1:
                nxt = len(trans)
                trans[node][ci] = nxt
                trans.append([-1] * k)
                bad.append(False)
            node = nxt
        bad[node] = True

    fail = [0] * len(trans)
    q = deque()
    for ci in range(k):
        nxt = trans[0][ci]
        if nxt != -1:
            fail[nxt] = 0
            q.append(nxt)
        else:
            trans[0][ci] = 0

    while q:
        u = q.popleft()
        if bad[fail[u]]:
            bad[u] = True
        for ci in range(k):
            v = trans[u][ci]
            if v != -1:
                if bad[u]:
                    bad[v] = True
                fail[v] = trans[fail[u]][ci]
                q.append(v)
            else:
                trans[u][ci] = trans[fail[u]][ci]

    valid_idx = {}
    for u in range(len(trans)):
        if not bad[u]:
            valid_idx[u] = len(valid_idx)

    m = len(valid_idx)
    mat = [[0] * m for _ in range(m)]
    for u, i in valid_idx.items():
        for ci in range(k):
            v = trans[u][ci]
            if not bad[v]:
                mat[i][valid_idx[v]] += 1

    def mat_mul(a: list[list[int]], b: list[list[int]]) -> list[list[int]]:
        res = [[0] * m for _ in range(m)]
        for i in range(m):
            ai = a[i]
            ri = res[i]
            for mid in range(m):
                val = ai[mid]
                if val:
                    bm = b[mid]
                    for j in range(m):
                        ri[j] = (ri[j] + val * bm[j]) % MOD
        return res

    vec = [0] * m
    vec[0] = 1
    exp = n
    base = mat
    while exp > 0:
        if exp & 1:
            nxt_vec = [0] * m
            for i in range(m):
                vi = vec[i]
                if vi:
                    bi = base[i]
                    for j in range(m):
                        nxt_vec[j] = (nxt_vec[j] + vi * bi[j]) % MOD
            vec = nxt_vec
        exp >>= 1
        if exp > 0:
            base = mat_mul(base, base)

    return sum(vec) % MOD
